    /* 2. Dạng lớp theo mục chứa */
    var form = icon.closest('sd-table') ? 'lig' : (icon.closest('sd-form-render') ? 'short' : '');
    if (!form) return;
    cl.remove('notranslate');
    cl.remove('mat-icon-no-color');
