      if (!fi) { fi = document.createElement('span'); fi.className = 'mat-focus-indicator'; btn.appendChild(fi); }
      if (!tt) { tt = document.createElement('span'); tt.className = 'mat-mdc-button-touch-target'; btn.appendChild(tt); }
