    var order = ctx === '' ? [kindAttr, 'class', 'type', 'data-disabled', 'data-loading', 'disabled']
      : (ctx === 'B' ? ['type', 'class', 'disabled', 'data-disabled', 'data-loading'] : ['type', 'class', 'data-disabled', 'data-loading', 'disabled']);
    if (ctx === '') { if (!btn.hasAttribute(kindAttr)) btn.setAttribute(kindAttr, ''); }
