    unknown:     { icon: 'help_outline',           color: 'info',    filled: false },
    new:         { icon: 'circle',                 color: 'info',    filled: true },
    pending:     { icon: 'pending',                color: 'info',    filled: false },
    waiting:     { icon: 'access_time',            color: 'info',    filled: false },
    inprogress:  { icon: 'timelapse',              color: 'info',    filled: false },
    checked:     { icon: 'task_alt',               color: 'success', filled: false },
    active:      { icon: 'play_circle',            color: 'success', filled: true },
    success:     { icon: 'check_circle',           color: 'success', filled: true },
    paused:      { icon: 'pause_circle',           color: 'warning', filled: true },
    warning:     { icon: 'warning',                color: 'warning', filled: true },
    blocked:     { icon: 'block',                  color: 'error',   filled: false },
    error:       { icon: 'error',                  color: 'error',   filled: true },
    cancelled:   { icon: 'cancel',                 color: 'secondary', filled: true },
    deactivated: { icon: 'remove_circle',          color: 'secondary', filled: true },
    removed:     { icon: 'remove_circle_outline',  color: 'secondary', filled: false },
    approved:    { icon: 'thumb_up',               color: 'success', filled: false },
    denied:      { icon: 'thumb_down',             color: 'error',   filled: false },
    /* Trạng thái nghiệp vụ của prototype — bổ sung 2026-10-14, PD DUYỆT 2026-10-14 (Builder chọn: Sắp hiệu lực = info
       theo nhóm Processing, Hết hiệu lực = secondary theo nhóm End). */
    draft:       { icon: 'edit_note',              color: 'secondary', filled: false },
    upcoming:    { icon: 'update',                 color: 'info',    filled: false },
    expired:     { icon: 'event_busy',             color: 'secondary', filled: false },
