      menu.classList.toggle('mat-mdc-select-panel-above', up);
      pane.style.top = (up ? top - 4 - h : bottom + 4) + 'px';
      var w = Math.max(menu.offsetWidth, r.width);
      pane.style.left = Math.max(8, Math.min(r.left, vw - 8 - w)) + 'px';
