        var header = document.createElement('mat-tab-header');
        header.className = 'mat-mdc-tab-header';
        var mkPag = function (side) {
          var d = document.createElement('div');
          d.setAttribute('aria-hidden', 'true');
          d.className = 'mat-mdc-tab-header-pagination mat-mdc-tab-header-pagination-' + side + ' mat-ripple mat-mdc-tab-header-pagination-disabled';
          var c = document.createElement('div'); c.className = 'mat-mdc-tab-header-pagination-chevron';
          d.appendChild(c);
          d.addEventListener('click', function () { self._scrollStep(side === 'before' ? -1 : 1); });
          return d;
        };
        this._prevBtn = mkPag('before');
        this._nextBtn = mkPag('after');
        var container = document.createElement('div'); container.className = 'mat-mdc-tab-label-container';
        var list = document.createElement('div'); list.setAttribute('role', 'tablist'); list.className = 'mat-mdc-tab-list';
        list.style.transform = 'translateX(0px)';
