      html += '</div>';
      html += '<sd-query-field-picker></sd-query-field-picker>';

      /* Vạch ngăn giữa vùng chip và vùng hành động — catalog `#c-query-bar`
         đặt `<span class="c-bar-divider">` NGAY TRƯỚC `.c-query-bar__actions`
         (1px, cao tối thiểu 28px, màu #e2e4e7). Kit thiếu hẳn vạch này. */
      html += '<sd-query-actions-bar><span class="c-bar-divider" aria-hidden="true"></span>';
      html += '<div class="c-query-bar__actions">';
      if (this._flag('show-logic-toggle', 'showlogictoggle') && (this._filters || []).length >= 2) {
        html += this._renderLogicToggle();
      }
      /* showClearAll = input(true) trong thư viện; _flag mặc định false nên phải
         gọi riêng (rà soát 2026-10-10). */
      if (this._flagDefaultTrue('showClearAll', 'show-clear-all', 'showclearall') && (this._filters || []).length > 0) {
        html += '<button type="button" class="c-clear-all" data-qb-role="clear-all" aria-label="Xoá hết bộ lọc" title="Xóa tất cả (' + this._countCommitted() + ')">' +
          '<mat-icon class="mat-icon material-icons-outlined" aria-hidden="true">delete_sweep</mat-icon></button>';
      }
      if (this._flag('show-saved-filters', 'showsavedfilters')) html += this._renderSavedTrigger();
      html += '<button type="button" class="c-search-trigger" data-qb-role="apply-btn" aria-label="Tìm kiếm" title="Tìm kiếm">' +
        '<mat-icon class="mat-icon material-icons-outlined" aria-hidden="true">search</mat-icon></button>';
      html += '</div></sd-query-actions-bar>';
      html += '</div>';

