      if (!panel) return;
      var r = this._btn.getBoundingClientRect(), pw = panel.offsetWidth, ph = panel.offsetHeight;
      var vw = document.documentElement.clientWidth, vh = document.documentElement.clientHeight;
      var below = r.bottom + ph <= vh || r.top - ph < 0, after = r.left + pw <= vw || r.right - pw < 0;
      panel.className = 'mat-mdc-menu-panel c-op-menu mat-menu-' + (after ? 'after' : 'before') + ' mat-menu-' + (below ? 'below' : 'above');
      this._pane.style.top = (below ? r.bottom : r.top - ph) + 'px';
      this._pane.style.left = (after ? r.left : r.right - pw) + 'px';
