        var pick = function (attr) { return kids.filter(function (k) { return k.hasAttribute(attr); }); };
        this._slots = { title: pick('sdtitle'), body: pick('sdbody'), footer: pick('sdfooter') };
        /* host không có template riêng — mọi con được chiếu vào panel; phần không khớp
           selector nào bị bỏ (ng-content chỉ có 3 select) */
        this.innerHTML = '';
