      /* thứ tự lớp như Angular: lớp tĩnh rồi tới các [class.x] theo thứ tự khai báo */
      var keep = Array.prototype.slice.call(p.classList).filter(function (c) { return c !== 'modal-resizable'; });
      var cls = ['modal-resizable'];
      if (this._opened) cls.push('modal-resizable--active');
