  /* chuỗi vi của thư viện (core.component.import-excel.* · core.excel.*) */
  var SD_IMPORT_EXCEL_TEXT = {
    title: 'Nhập dữ liệu Excel', seeAll: 'Xem tất cả', validRows: 'Số dòng dữ liệu hợp lệ',
    errorRows: 'Số dòng dữ liệu có lỗi', warningRows: 'Số dòng dữ liệu có cảnh báo', status: 'Trạng thái',
    validData: 'Dữ liệu hợp lệ', downloadTemplateTooltip: 'Nhấn để tải tệp mẫu về máy',
    noDataUpload: 'Chưa có dữ liệu tải lên', clickHereTemplate: 'Nhấn vào đây để tải tệp mẫu',
    upload: 'Tải lên', download: 'Tải về', confirmSave: 'Xác nhận & Lưu',
    noDataInFile: 'Tệp tin không có dữ liệu', rowLimit: 'Giới hạn tải lên {limit} dòng',
    required: 'Dữ liệu bắt buộc', minLength: 'Độ dài chuỗi tối thiểu: {min}', maxLength: 'Độ dài chuỗi tối đa: {max}',
    notANumber: '{value} không phải số hợp lệ', belowMin: '{value} không thỏa giá trị tối thiểu: {min}',
    aboveMax: '{value} không thỏa giá trị tối đa: {max}', invalidBool: 'Vui lòng nhập giá trị hợp lệ true, false, 1, 0',
    invalidValue: 'Giá trị {value} không hợp lệ', valueNotInList: 'Giá trị {value} không thuộc danh sách cho phép [{list}]',
    invalidDateFormat: 'Ngày {value} không đúng định dạng {format}', genericError: 'Có lỗi xảy ra',
    messageColumn: 'Thông báo', success: 'Thành công',
    cannotReadFile: 'Không đọc được nội dung file', noSheet: 'File Excel không có sheet dữ liệu',
    uploadInvalidFormat: '[{name}] File tải lên không đúng định dạng. Vui lòng chọn lại',
    uploadInvalidSize: '[{name}] Kích thước file không hợp lệ. Vui lòng chọn một file khác'
  };
  function sdIeT(key, p) {
    var s = SD_IMPORT_EXCEL_TEXT[key] || key;
    if (p) Object.keys(p).forEach(function (k) { s = s.split('{' + k + '}').join(p[k]); });
    return s;
  }

  /* ── exceljs (nạp lười) ── */
