    get defaultEntity() { return this._default || {}; }
    /* biến phụ cho hàm điều kiện của cấu hình cũ kit */
    set setVariables(v) { this._vars = v || {}; if (this._ready) this._render(); }
    get setVariables() { return this._vars || {}; }

    get viewed() { return this.hasAttribute('viewed') && this.getAttribute('viewed') !== 'false'; }
