        return html +
          '<sd-input-number class="qb-rel-amount" size="sm" hideInlineError' +
            (rule.data == null || rule.data === '' ? '' : ' value="' + escAttr(rule.data) + '"') + dis + '></sd-input-number>' +
          this._sel('qb-rel-unit', T.dateUnits.map(function (u) { return { id: u, name: u }; }),
            rule.unit || T.dateUnits[0]);
